// Traduction à faire relire.

export default {
  rules: {
    1: {
      theme: "Human Oversight & Accountability",
      summary: "AI remains under human control at every stage of its use.",
      question: "Checking each AI output (rule 1) or monitoring the system over time (rule 2): who does what where you work?",
    },
    2: {
      theme: "Security & Robustness",
      summary: "Use of AI systems that are effective, reliable and secure.",
      question: "Testing, monitoring, being able to stop the system (rule 2): how is that different from checking each output before using it (rule 1)?",
    },
    3: {
      theme: "Data & AI Governance",
      summary: "Bodies are set up to ensure oversight and enforcement of AI policies.",
      question: "Which bodies oversee AI projects where you work, and at what point should you call on them?",
    },
    4: {
      theme: "Environmental Impact",
      summary: "Commitment to stabilising the carbon emissions linked to AI operations.",
      question: "How can you track the carbon emissions linked to your use of AI: carbon calculator, model size, number of requests…? What do you already use?",
    },
    5: {
      theme: "Trust & Transparency",
      summary: "Clear and systematic information is provided when interacting with AI systems.",
      question: "In your tools, does the user always know they are dealing with an AI, and do they know its limits?",
    },
    6: {
      theme: "Fairness & Inclusion",
      summary: "Training on responsible AI, ethics and sustainability is offered to everyone.",
      question: "Is responsible AI training really accessible to everyone where you work, whatever their job and level?",
    },
    7: {
      theme: "Human-Centred AI",
      summary: "Every AI system must create value for customers, employees and society.",
      question: "What concrete need justifies this use of AI, and how can you check that it really frees up time?",
    },
  },
  cards: {
    "classique:R1-C01": { text: "AI writes code. Every delivery goes through code review and testing." },
    "classique:R1-C02": { text: "An AI suggests replies to customers. The adviser always chooses the final reply from those suggested by the AI." },
    "classique:R1-C03": { text: "We use Copilot to write meeting minutes. The manager always proofreads and approves them before they are sent out." },
    "classique:R1-C04": { text: "A model flags potential fraud. The fraud expert decides whether or not to open an investigation." },
    "classique:R1-C05": { text: "An AI tool reads accident report forms and proposes a split of liability. The claims handler approves or corrects it before informing the policyholder." },
    "classique:R1-C06": { text: "An AI tool pre-fills a policy application from the scanned driving licence. The handler checks every field before approving the contract." },
    "classique:R1-C07": { text: "An AI proposes how to match incoming payments. The accountant approves every doubtful match before it is posted to the accounts." },
    "classique:R1-C08": { text: "An AI tool reads hospital invoices and proposes a reimbursement amount. The handler approves each proposal before payment." },
    "classique:R1-C09": { text: "An AI tool ranks the CVs received for a job. The recruiter opens every rejected application before approving the list of rejections." },
    "classique:R1-C10": { text: "An AI tool flags files where an exclusion clause seems to apply. The lawyer reviews the contract and alone decides on any refusal of cover." },
    "classique:R1-C11": { text: "An AI assistant summarises the call when it ends. The adviser rereads and corrects the summary before saving it to the customer's file." },
    "classique:R1-C12": { text: "An AI tool spots motor claims that call for an expert assessment. The handler alone decides whether or not to appoint an expert." },
    "classique:R1-C13": { text: "A model flags dental quotes with unusual prices. The handler calls the practitioner before any decision on coverage." },
    "classique:R1-C14": { text: "An AI prepares the month-end closing entries. The chief accountant approves them one by one before they are posted." },
    "classique:R1-U01": { text: "Price increase decisions are made automatically by the AI without any human intervention.", why: "A decision with a major impact on the customer is made without any human supervision: the AI decides alone instead of assisting." },
    "classique:R1-U02": { text: "An AI tool calculates compensation for small home claims. Settlements are paid straight into the policyholder's account, with no handler involved.", why: "A settlement is paid without any human approval: the AI alone decides on compensation instead of assisting the handler." },
    "classique:R1-U03": { text: "An AI assistant sends replies to simple complaints. Each adviser checks the history of their files and flags the replies that need correcting.", why: "Replies go out before any check: the adviser only reviews them after sending, when an error can no longer be prevented." },
    "classique:R1-U04": { text: "Routine optical reimbursements are approved by the AI. The handler deals with complex files and those the policyholder disputes.", why: "The AI alone decides on routine reimbursements: nobody reviews them unless the policyholder disputes them." },
    "classique:R1-U05": { text: "An AI proposes a split of liability from accident report forms. The handler approves the proposals with a low confidence level.", why: "Proposals the AI considers reliable are never checked: a high confidence level does not guarantee accuracy, and that is where nobody looks." },
    "classique:R1-U06": { text: "An AI tool ranks the CVs received for a job. The recruiter rereads the top-ranked applications and approves the shortlist for interviews.", why: "Applications rejected by the AI are never reread: the AI alone eliminates candidates, and human approval only covers those shortlisted." },
    "classique:R2-C01": { text: "Before going live, the AI model was tested on several representative datasets to assess its reliability and performance." },
    "classique:R2-C02": { text: "Business teams take part in testing to check that the results produced match real needs on the ground." },
    "classique:R2-C03": { text: "A process makes it possible to quickly suspend or switch off the system if a major problem is identified." },
    "classique:R2-C04": { text: "A team monitors the model's performance after deployment to quickly detect any degradation or unexpected behaviour." },
    "classique:R2-C05": { text: "When the AI lacks information or is not sure of its answer, it says so instead of making up an answer." },
    "classique:R2-C06": { text: "Regular audits check that the system still meets the expected quality and security levels." },
    "classique:R2-C07": { text: "Before being rolled out to the call centre, the call transcription tool was tested on real calls: accents, elderly voices, background noise, street names." },
    "classique:R2-C08": { text: "For the first three closings, the new payment-matching tool runs alongside the old process, and the team compares the results." },
    "classique:R2-C09": { text: "If the invoice-reading tool gets an amount wrong, a button switches it off and invoices go back to manual entry while it is fixed." },
    "classique:R2-C10": { text: "When the reading AI cannot read a date on a supporting document, it leaves the field blank and flags it to the handler." },
    "classique:R2-C11": { text: "Access to the payroll AI tool is restricted to authorised payroll staff, with a personal account and two-factor authentication." },
    "classique:R2-C12": { text: "The handlers' AI assistant only opens the files in their own portfolio. Access is logged and reviewed regularly." },
    "classique:R2-C13": { text: "Every month, a lawyer compares the summaries produced by the AI with a sample of files they have reread, to spot any drop in quality." },
    "classique:R2-C14": { text: "After each update of the contribution rates, the payroll team reruns the AI tool on payslips already checked and compares the results." },
    "classique:R2-C15": { text: "Before deployment, the AI tool that reads garage invoices is tested on crumpled scans and handwritten invoices, not just on clean PDFs." },
    "classique:R2-U01": { text: "The request-sorting model won over the business teams during a demo. It goes live the following week.", why: "A successful demo is no substitute for representative tests: the model goes live without its reliability being validated." },
    "classique:R2-U02": { text: "Handlers use the AI file assistant with a single team login, whose password is displayed on the wall of the office.", why: "A shared, visible login makes access insecure and untraceable: nobody knows who is viewing which customer files." },
    "classique:R2-U03": { text: "The garage invoice-reading tool is rolled out to all handlers as soon as it is delivered; a channel reports errors to the project team.", why: "The tool is rolled out on delivery, before any reliability testing: it is only known through the errors handlers happen to notice." },
    "classique:R2-U04": { text: "Management approved the AI assistant's fallback procedure when it was written; it will be applied for the first time during an outage.", why: "A fallback mode that has never been tested is not reliable: nobody knows whether it will work on the day of a real outage." },
    "classique:R2-U05": { text: "Every month, the department measures the reliability of the invoice-reading tool based on the invoices the accountants have corrected.", why: "Only errors noticed by the accountants are counted: undetected errors escape the measure, so reliability is overestimated." },
    "classique:R2-U06": { text: "The supplier updates the model that reads dates on supporting documents every month. The team reads the release notes and approves go-live.", why: "The team reads the release notes but does not test the new model on its own cases: a regression would go unnoticed." },
    "classique:R3-C01": { text: "Before putting the chatbot into production, the team presents the project to a committee that checks it is aligned with Group AI policies." },
    "classique:R3-C02": { text: "A Data Science team has documented its model: purpose; data used; owners; identified risks. The documentation is updated with every change." },
    "classique:R3-C03": { text: "We use an AI assistant approved by AXA. Before deployment, the project was declared to the AI governance body. The compliance and security teams were consulted." },
    "classique:R3-C04": { text: "An AI project launched in several countries applies the same control standards and the same governance principles defined by AXA Group." },
    "classique:R3-C05": { text: "A team wants to reuse an AI model already used in another AXA country. Before deploying it locally, it checks that the data, rules and constraints fit the French context." },
    "classique:R3-C06": { text: "The automatic invoice-reading project is declared to the AI body, with the data processed, the designated owner and the planned controls." },
    "classique:R3-C07": { text: "The supplier of the unpaid-premium scoring tool changes its model. The team declares it to AI governance, which approves before the tool is used again." },
    "classique:R3-C08": { text: "The team leader keeps the department's list of AI uses up to date: tool, scope, data processed and designated contact person." },
    "classique:R3-C09": { text: "A branch asks for access to the document-reading tool. Deployment waits for compliance's opinion on the data that will be processed in it." },
    "classique:R3-C10": { text: "A handler comes up with a use of AI to sort incoming mail. They submit it to the department's AI contact, who puts it into the group approval process." },
    "classique:R3-C11": { text: "The contact centre displays the list of authorised AI tools. It is kept up to date with governance and can be consulted by all advisers." },
    "classique:R3-C12": { text: "An AI contact person in the call centre passes on the charter's rules to advisers and reports the uses they are trying out to governance." },
    "classique:R3-C13": { text: "A manager suggests a new use of AI to prepare annual reviews. The project goes through compliance and the DPO before any trial." },
    "classique:R3-C14": { text: "Before using the invoice-reading AI on health data, the team declares it to the AI contact and obtains the data protection officer's opinion." },
    "classique:R3-C15": { text: "Any change to the instructions of the letter-writing AI assistant is submitted to the business's AI contact before being applied to the whole team." },
    "classique:R3-U01": { text: "A team makes an AI assistant it has developed available to its colleagues. It will declare it to governance once the final version is ready.", why: "This is “shadow AI”: the tool is deployed before any declaration to AI governance, without compliance or security checks." },
    "classique:R3-U02": { text: "A handler builds a reminder assistant with a consumer AI tool. Their manager approved it verbally and the team has been using it for a month.", why: "A manager's verbal approval does not replace declaration to AI governance: the tool runs without compliance or security checks." },
    "classique:R3-U03": { text: "The HR team extends the AI tool approved by governance for job ads to annual reviews, on the basis of the initial authorisation.", why: "The new use involves more sensitive data, with no new declaration or re-approval: the initial authorisation does not cover it." },
    "classique:R3-U04": { text: "A lawyer picked an off-the-shelf AI assistant on their own to summarise complaint files, which they anonymise by hand before entering them.", why: "The tool was chosen outside the approval process, and manual anonymisation is not checked: complainants' data may leak." },
    "classique:R3-U05": { text: "The file summariser was approved by governance at launch. It has since been processing other types of files; the documentation dates from the launch.", why: "The use has changed since approval without the documentation or governance keeping up: the oversight no longer covers what the tool does." },
    "classique:R3-U06": { text: "The payment-matching tool's provider was approved by governance. Its hosting subcontractors are listed in its contract with the purchasing department.", why: "Only the purchasing department knows the subcontractors: governance approved the provider without examining who hosts the data." },
    "classique:R4-C01": { text: "The team limits pointless generations. It gradually refines its prompts instead of firing off dozens of requests in a row." },
    "classique:R4-C02": { text: "Before launching a new AI project, the team uses the Group's carbon calculator to estimate the environmental impact of the planned solution." },
    "classique:R4-C03": { text: "To summarise meeting minutes, the team uses a lightweight model that performs well enough for the task. It compared several options before choosing." },
    "classique:R4-C04": { text: "Before automating a repetitive task with AI, the team checks whether a simple script would do, to avoid unnecessary consumption." },
    "classique:R4-C05": { text: "Two models give similar results. The team chooses the one that uses fewer resources while still meeting business needs." },
    "classique:R4-C06": { text: "To spot duplicate invoices, the team uses a calculation rule on the number and amount, rather than an AI model." },
    "classique:R4-C07": { text: "For standard reminders, the team uses a lightweight generative AI model. The large model is kept for complex litigation letters." },
    "classique:R4-C08": { text: "The reading AI is only run on handwritten or poor-quality documents. Standard documents are read by a conventional, more frugal tool." },
    "classique:R4-C09": { text: "The AI summary tool is run only once, when the file is complete, and not every time the customer adds a document." },
    "classique:R4-C10": { text: "Before signing, the department asks the call transcription provider for the carbon footprint of its offer and compares it with other solutions." },
    "classique:R4-C11": { text: "After three months, the team finds that nobody reads the AI summaries of simple emails. It stops generating them." },
    "classique:R4-C12": { text: "The team generates a standard letter with AI just once, then saves it as a reusable template instead of regenerating it for each mailing." },
    "classique:R4-C13": { text: "Before asking generative AI to write a standard letter, the handler checks whether an approved letter template already exists in the library." },
    "classique:R4-C14": { text: "Before having photos analysed by an AI, the handler selects the few shots that are useful for assessing the damage." },
    "classique:R4-C15": { text: "The archiving AI assistant only processes new or changed staff files, not the whole history on every run." },
    "classique:R4-U01": { text: "To write its internal summaries, the team uses the most powerful AI model in the catalogue by default, for all its requests.", why: "The most powerful model is used by default, even when a more frugal model would do: environmental impact is not taken into account." },
    "classique:R4-U02": { text: "For each reminder, the handler asks generative AI for a dozen versions, then keeps the most natural one. They do this for every letter.", why: "Generating a dozen versions of each letter multiplies requests needlessly, with no thought for AI's carbon footprint." },
    "classique:R4-U03": { text: "For each claim, generative AI writes a summary of the file, in addition to the summary written by the handler.", why: "The AI summary duplicates work already done: needless requests, without asking whether the need justifies them or what the impact is." },
    "classique:R4-U04": { text: "Advisers check the spelling of their emails with generative AI, as an alternative to the email spell checker.", why: "A tool that is already available is replaced by a generative AI that is far more resource-hungry, without any prior comparison." },
    "classique:R4-U05": { text: "A small model summarises policy amendments. The handler can regenerate the summary until they are happy with the tone.", why: "Repeated regenerations multiply requests: the gain from a small model is cancelled out, for lack of a set limit." },
    "classique:R4-U06": { text: "Every month, the department measures the growth in the number of generative AI users and sets itself the goal of doubling it by the end of the year.", why: "The goal targets growth in usage, not stabilising emissions: consumption is not tracked." },
    "classique:R5-C01": { text: "The application clearly tells the user that AI can make mistakes and that some answers need to be checked." },
    "classique:R5-C02": { text: "When minutes are generated automatically, a notice says they were produced with the help of AI and invites the user to proofread them before sending." },
    "classique:R5-C03": { text: "Employees chat with an HR assistant. A visible banner clearly states: “You are currently talking to an assistant powered by artificial intelligence.”" },
    "classique:R5-C04": { text: "When the AI assistant gives a wrong answer, the team reports it quickly, fixes it and learns from it, without looking for someone to blame." },
    "classique:R5-C05": { text: "Users can easily tell when an answer comes from an AI or from a human adviser." },
    "classique:R5-C06": { text: "The system's performance is monitored regularly to detect errors or drifts that could affect the quality of answers." },
    "classique:R5-C07": { text: "An employee notices that the data used by the AI tool is incomplete. They report it before the results are used to make a decision." },
    "classique:R5-C08": { text: "The unpaid-premium dashboard states that the forecast comes from an AI model, with its update date and known limits." },
    "classique:R5-C09": { text: "In the tool, each field pre-filled by AI is shown with a distinct marker, to tell it apart from human input." },
    "classique:R5-C10": { text: "When a policyholder asks how the AI classified their complaint, the handler explains in simple terms which elements were taken into account." },
    "classique:R5-C11": { text: "The ombudsman receives the file with a note stating which AI tools were used to analyse the documents, and at which stage of processing." },
    "classique:R5-C12": { text: "Job ads state that an AI helps sort applications, and say who to contact for an explanation." },
    "classique:R5-C13": { text: "The payroll portal reminds employees that the AI assistant's answers are for guidance only and that only the payslip is authoritative." },
    "classique:R5-C14": { text: "When the AI tool reads an amount on an invoice, it also shows its confidence level and where in the document it found it." },
    "classique:R5-C15": { text: "The voice server announces at the start of the call that the transcription is done by an AI, and lets the policyholder refuse it." },
    "classique:R5-U01": { text: "A chatbot answers customer requests, signing with an adviser's first name. Customers appreciate this personal touch.", why: "The chatbot passes itself off as an adviser: customers do not know they are talking to an AI, and their satisfaction does not make up for this lack of transparency." },
    "classique:R5-U02": { text: "A customer asks whether an AI processed their file. The handler replies that their file is being reviewed by an adviser, without mentioning the scoring.", why: "The handler hides the use of AI from a customer who asks directly: transparency requires a clear answer." },
    "classique:R5-U03": { text: "An AI assistant suggests replies to customers. The adviser rereads them, signs them with their name and sends them from their own mailbox.", why: "The customer does not know the AI was involved: rereading a reply does not remove the need to disclose the use of AI." },
    "classique:R5-U04": { text: "A risk score calculated by the AI appears in each policyholder's file, presented as contract data just like the rest.", why: "The score is presented without its limits or reliability: handlers do not know how much to trust it." },
    "classique:R5-U05": { text: "An AI transcribes calls to feed the file. The adviser tells the policyholder about the transcription if they ask.", why: "The information is only given if the policyholder asks for it: it is neither clear nor systematic." },
    "classique:R5-U06": { text: "AI file summaries carry the label “AI-generated”; the handler removes it after proofreading, even if they only changed one sentence.", why: "A proofread summary is still largely produced by AI: without the label, the reader no longer knows what to double-check." },
    "classique:R6-C01": { text: "A new AI training course is offered to all employees, whatever their job or technical level. Beginner, intermediate and advanced tracks are available." },
    "classique:R6-C02": { text: "All employees concerned take a mandatory module on responsible uses of AI, its risks and good practices." },
    "classique:R6-C03": { text: "An internal community lets employees share their good practices and questions about responsible AI." },
    "classique:R6-C04": { text: "Employees who are new to AI get extra hands-on workshops so they can progress at their own pace." },
    "classique:R6-C05": { text: "The most advanced employees occasionally support their colleagues on their first use cases." },
    "classique:R6-C06": { text: "The department includes a responsible AI module in the induction of new handlers, with examples drawn from reminders and payment matching." },
    "classique:R6-C07": { text: "Accountants who are less comfortable with digital tools attend a hands-on workshop in a small group before switching to the AI payment-matching tool." },
    "classique:R6-C08": { text: "When the invoice-reading tool changes, a training session is organised for all accountants, not just the designated experts." },
    "classique:R6-C09": { text: "Half a day per quarter is set aside in the back-office schedule to practise with the AI tool on real department files." },
    "classique:R6-C10": { text: "The department's apprentices and temporary staff take the module on responsible use of AI before getting access to the document-reading tool." },
    "classique:R6-C11": { text: "The responsible AI training exists in a version adapted for employees with disabilities, with subtitles and easy-to-read materials." },
    "classique:R6-C12": { text: "Call centre advisers take AI training during working hours, with cases drawn from their own calls and emails." },
    "classique:R6-C13": { text: "Team leaders take the responsible AI training before their teams so they can answer advisers' questions." },
    "classique:R6-C14": { text: "The training department runs AI workshops in branches and processing centres, not just at head office." },
    "classique:R6-C15": { text: "As soon as they join, new handlers take a module on what can and cannot be entered into an AI tool: health data, medical confidentiality." },
    "classique:R6-U01": { text: "AI training is offered to technical and Data teams. Other business lines receive a summary of their work.", why: "Training is reserved for a technical elite: other business lines are left out even though they also use AI. Access to training must be fair." },
    "classique:R6-U02": { text: "An AI tool recommends AI training paths. It only offers the advanced paths to employees classed as managers.", why: "Access to advanced training depends on status, not need: training is not offered fairly to everyone." },
    "classique:R6-U03": { text: "The mandatory responsible AI module is held by videoconference on Tuesday mornings, a slot when shift teams are not at work.", why: "Shift teams have no suitable slot: in practice, access to training is not fair." },
    "classique:R6-U04": { text: "The AI training catalogue is sent to managers every quarter, who are free to pass it on to their teams or to choose who signs up.", why: "Access depends on managers' goodwill: not all handlers receive the information, so access to training is not fair." },
    "classique:R6-U05": { text: "Registration for the AI training opens on a Monday at 9 a.m. for 30 places, allocated in order; field teams are in customer meetings at that time.", why: "Places go on a first-come basis: field teams, in meetings at that time, are left out, so access is not fair." },
    "classique:R6-U06": { text: "The responsible AI training is held at head office, three half-days a year; travel costs are borne by the regional branches.", why: "Regional branches pay for travel: not all distant teams can attend, so access is not equal." },
    "classique:R7-C01": { text: "An AI prepares the relevant information before a customer meeting to reduce admin tasks and let the adviser spend more time listening and advising." },
    "classique:R7-C02": { text: "An AI assistant answers questions about internal procedures to help newcomers become more autonomous." },
    "classique:R7-C03": { text: "An AI analyses files to identify more quickly the situations that need a human expert to step in." },
    "classique:R7-C04": { text: "An AI assistant helps customers understand their cover by rephrasing the information in simpler language." },
    "classique:R7-C05": { text: "An AI solution automatically generates subtitles and transcripts to make content accessible to more employees." },
    "classique:R7-C06": { text: "An AI pre-fills payment plans for policyholders in difficulty, leaving the handler time to call them and find a suitable solution." },
    "classique:R7-C07": { text: "Together with the handlers, the team measures whether the pre-filling AI reduces re-keying before extending it to other products." },
    "classique:R7-C08": { text: "An AI tool spots words in a complaint that signal financial distress or a death, so the handler calls the policyholder as a priority." },
    "classique:R7-C09": { text: "Before deploying the summarisation tool, the team asks handlers which tasks slow them down most and chooses the use of AI accordingly." },
    "classique:R7-C10": { text: "An AI tool spots customers who call back about the same claim and alerts the adviser so they can offer personalised follow-up." },
    "classique:R7-C11": { text: "An AI drafts the call report, which frees up time for advisers to call back elderly or isolated customers." },
    "classique:R7-C12": { text: "An AI prepares a newcomer's welcome pack according to their role. The HR assistant spends the time saved supporting them." },
    "classique:R7-C13": { text: "An AI rewrites refusal letters in plain language, with the possible next steps. Policyholders call back less to ask what they mean." },
    "classique:R7-C14": { text: "An AI tool spots policyholders on long-term sick leave with no contact for months. The handler calls them back to offer support." },
    "classique:R7-C15": { text: "After a storm, an AI groups claims by town and type of damage, so the worst-hit policyholders can be called back first." },
    "classique:R7-U01": { text: "A team adds a generative AI feature to its app to announce it at the next trade fair. Customer needs will be looked at later.", why: "AI is used for show, with no identified need or measured benefit for customers or employees." },
    "classique:R7-U02": { text: "An AI replaces follow-up calls to policyholders on disability benefits with automatic text messages. Handlers no longer have direct contact with them.", why: "The AI removes the human connection with vulnerable policyholders: it creates volume gains but no value for customers or employees." },
    "classique:R7-U03": { text: "Every week, an AI tool spots remote workers who are rarely online and informs their manager so they can contact them.", why: "The AI monitors employees instead of helping them: it creates distrust, not value for them." },
    "classique:R7-U04": { text: "The team deploys an AI tool for chasing unpaid premiums, assessed on the number of payments obtained, including from customers in financial difficulty.", why: "Effectiveness is measured without looking at the effect on customers in difficulty: no human benefit is considered." },
    "classique:R7-U05": { text: "An AI assistant answers common questions and suggests the customer rephrase their request or check the FAQ.", why: "The customer in difficulty is not directed to an adviser: the AI holds on to them when it should free up time for complex cases." },
    "classique:R7-U06": { text: "An AI prepares the file before each policyholder call. The team tracks the number of calls handled per hour and per handler.", why: "The time saved is reinvested in throughput, not in listening: the AI was supposed to free up time for advice." },
    "po:R1-C01": { text: "AI writes user stories from workshop notes. The PO rereads and corrects them, and alone decides what goes into the backlog." },
    "po:R1-C02": { text: "An assistant proposes a backlog prioritisation. The PO uses it as a starting point and owns the final trade-off in front of stakeholders." },
    "po:R1-C03": { text: "The acceptance criteria generated by AI are reviewed with the developers and testers before the sprint." },
    "po:R1-C04": { text: "A model suggests customer requests to handle first. The PO checks sensitive cases before any roadmap decision." },
    "po:R1-C05": { text: "An AI summarises twenty user interviews into broad trends. The PO rereads raw verbatims before drawing any conclusion about the need." },
    "po:R1-C06": { text: "AI splits an epic into stories. The team reviews the split during refinement and changes several before planning them." },
    "po:R1-C07": { text: "An AI tool generates test cases from the acceptance criteria. The PO and testers add the missing cases before acceptance testing." },
    "po:R1-C08": { text: "An AI proposes a roadmap scenario for the quarter. The PO tests it against the team's constraints and the business's expectations before presenting it." },
    "po:R1-C09": { text: "AI writes the sprint review minutes. The PO rereads them and corrects any misreported decisions before sending them to the sponsors." },
    "po:R1-C10": { text: "A tool automatically sorts support tickets by theme. The PO checks a sample every week and corrects doubtful groupings." },
    "po:R1-C11": { text: "An AI assistant compares three market solutions. The PO checks the key information with the suppliers before recommending a choice." },
    "po:R1-C12": { text: "AI detects duplicates in the backlog. The PO approves each merge before deleting a ticket." },
    "po:R1-C13": { text: "An AI-powered dashboard flags a risk of delay on a release. The PO discusses it with the team before moving the announced date." },
    "po:R1-C14": { text: "AI proposes value hypotheses for a new feature. The PO has them confirmed or refuted by user tests before investing." },
    "po:R1-U01": { text: "To save time, the team lets AI order the backlog automatically. The PO approves the sprint without rereading the proposed ranking.", why: "The PO hands their prioritisation decision over to AI: they remain accountable for the value delivered, and AI should assist without deciding for them." },
    "po:R1-U02": { text: "An AI decides which requests make the next release based on a value score. The PO simply tells the teams what is on the list.", why: "The roadmap trade-off is made by a score: the PO no longer exercises their responsibility for what is delivered." },
    "po:R1-U03": { text: "An AI assistant rewords and fleshes out stories before refinement. The enriched versions replace the originals in the backlog.", why: "The PO does not check what the AI changed: a story can change meaning without anyone having decided it." },
    "po:R1-U04": { text: "An AI tool writes the sprint review minutes and sends them to the sponsors. The PO can correct them in the team's tracking tool.", why: "The minutes go out before any proofreading: the PO can only correct misreported decisions after the fact." },
    "po:R1-U05": { text: "An AI reorders the backlog every night based on user feedback. The new order applies from the next morning.", why: "The new order applies without the PO's approval: they do not check each change in the ranking." },
    "po:R1-U06": { text: "An AI summarises twenty user interviews into broad themes. The PO approves each theme as soon as a verbatim illustrates it.", why: "Approval rests on a verbatim being present, not on its meaning: the PO does not check the themes against the original interviews." },
    "po:R2-C01": { text: "Before putting an AI feature into production, the PO has the model tested on real cases and edge cases, not just the demo scenario." },
    "po:R2-C02": { text: "The acceptance criteria for an AI feature include the expected behaviour when the model is wrong or unsure of its answer." },
    "po:R2-C03": { text: "The feature can be switched off quickly with a feature flag if a major problem arises." },
    "po:R2-C04": { text: "A review of answer quality is scheduled every sprint after going live." },
    "po:R2-C05": { text: "Business users take part in acceptance testing to check that the results match their day-to-day work." },
    "po:R2-C06": { text: "The team has defined quality indicators for the model (error rate, drift) and monitors how they change." },
    "po:R2-C07": { text: "Before using AI to analyse interviews, the PO tested it on a study already analysed by hand and compared the conclusions." },
    "po:R2-C08": { text: "The team tests the AI feature with trick questions, absurd inputs and misuse attempts before delivery." },
    "po:R2-C09": { text: "The AI feature is first opened to a small group of users, with close monitoring, before being extended to everyone." },
    "po:R2-C10": { text: "A quality indicator for the AI's answers appears in the product dashboard, with an alert threshold agreed with the team." },
    "po:R2-C11": { text: "When the AI supplier announces a new model version, the team reruns its test cases before adopting it." },
    "po:R2-C12": { text: "The backlog contains stories for plan B: what does the product do when the AI service is unavailable or too slow?" },
    "po:R2-C13": { text: "Before choosing an AI supplier, the PO checks its commitments on availability, security and reversibility." },
    "po:R2-C14": { text: "Feedback saying “the AI's answer is wrong” arrives in a dedicated channel and is handled first in the next sprint." },
    "po:R2-C15": { text: "The acceptance criteria specify the error level tolerated for the AI feature, agreed with the business." },
    "po:R2-U01": { text: "The demo to the sponsors is a success. The PO decides to ship the AI feature to all customers the following week, dropping the planned acceptance testing to meet the announced date.", why: "A successful demo does not prove the model is reliable: the feature goes live without representative tests." },
    "po:R2-U02": { text: "Nobody tracks the quality of the AI's answers after going live. The PO assumes it will stay the same as on delivery.", why: "No monitoring after deployment: a degradation or drift in the model would only be detected by users." },
    "po:R2-U03": { text: "The team tests the AI feature using test cases written by the developer who designed it, before delivery.", why: "The tests are written by the person who knows the system's limits: they do not cover the cases they did not think of." },
    "po:R2-U04": { text: "Every month, the supplier releases an improved version of its model, which the team deploys to production on the day it comes out.", why: "The new version is deployed the same day: the team does not check its behaviour before it reaches users." },
    "po:R2-U05": { text: "The dashboard tracks the quality of the AI's answers: the share of conversations completed without the user challenging them.", why: "The indicator only counts completed conversations: drop-outs and unreported errors go unnoticed, hiding the cases where the AI is wrong." },
    "po:R2-U06": { text: "The pilot with volunteer employees lasts one month; roll-out to all customers is planned for the date set in the roadmap.", why: "Moving to roll-out depends on the calendar, not on the pilot's results: an internal pilot does not guarantee the feature suits customers." },
    "po:R3-C01": { text: "Before starting to trial an AI assistant, the PO declares the project to the governance body and consults compliance and security." },
    "po:R3-C02": { text: "The product documentation states what the AI feature does, what data it uses, who is responsible for it and which risks are known. It is updated with every change." },
    "po:R3-C03": { text: "The PO checks an AI supplier's terms of use to make sure the company's data is not used to train its model." },
    "po:R3-C04": { text: "The PO anonymises customer verbatims before handing them to an AI tool to summarise." },
    "po:R3-C05": { text: "An AI feature already deployed in another country is reviewed with the DPO and compliance before being adopted locally." },
    "po:R3-C06": { text: "Before subscribing to an AI tool, the PO checks the list of tools approved by the company and asks for approval if the tool is not on it." },
    "po:R3-C07": { text: "Before recording user interviews to have them transcribed by AI, the PO obtains the participants' consent and explains the intended use." },
    "po:R3-C08": { text: "Tickets copied into an AI tool are first stripped of names, email addresses and contract numbers." },
    "po:R3-C09": { text: "The PO presents the planned AI feature to the company's AI committee before development starts." },
    "po:R3-C10": { text: "The PO makes sure that the data used to test the AI feature is test or anonymised data, not production data." },
    "po:R3-C11": { text: "The team's register of AI uses is kept up to date: tools used, data concerned, owner of each use." },
    "po:R3-C12": { text: "The contract with the AI supplier specifies where the data is hosted, how long it is kept and how to get it back." },
    "po:R3-C13": { text: "Before using AI on a partner's confidential documents, the PO obtains the partner's agreement." },
    "po:R3-C14": { text: "The roadmap allows the time needed for compliance and security approval of AI features." },
    "po:R3-C15": { text: "The PO checks with the DPO that the retention period for customer feedback analysed by AI complies with company policy." },
    "po:R3-U01": { text: "To move fast, the PO connects a consumer AI tool to the support ticket export, which contains customer data, and plans to regularise the situation once the gain is proven.", why: "This is “shadow AI”: customer data is sent to an unapproved tool, without declaration or any compliance or security check." },
    "po:R3-U02": { text: "To prepare a workshop, the PO pastes the full minutes of a customer interview, name and contract included, into a public AI.", why: "A customer's personal data is sent to an unapproved tool: this is a data leak, with no control or legal basis." },
    "po:R3-U03": { text: "To prepare refinement, the PO submits support tickets containing customer names to an off-the-shelf AI assistant, from the company account.", why: "Customers' personal data is sent to an unapproved tool: a company account does not replace governance approval." },
    "po:R3-U04": { text: "The PO uses an AI tool to summarise a partner's confidential documents and tells the partner about it at the steering committee.", why: "The partner did not give its agreement before its documents were used: the information comes too late." },
    "po:R3-U05": { text: "The chosen AI tool is on the company's approved list. The team turns on the history option, which was not examined during approval.", why: "The option changes how the data is used: the tool's approval does not cover this configuration, which was not declared." },
    "po:R3-U06": { text: "The PO has customer feedback analysed by AI after removing names and email addresses, with the contract number used as a reference.", why: "A contract number can identify the customer: the anonymisation is insufficient, and this data remains personal." },
    "po:R4-C01": { text: "Before launching an AI feature, the PO has its environmental impact estimated with the company calculator and takes it into account in the decision." },
    "po:R4-C02": { text: "To classify user feedback, the team compares a small model and a large model. It picks the more frugal one, as the results are equivalent." },
    "po:R4-C03": { text: "The team's prompts are refined before being run at scale, rather than multiplying successive generations." },
    "po:R4-C04": { text: "The PO asks whether a simple rule or a conventional search meets the need before turning to a generative AI model." },
    "po:R4-C05": { text: "The PO sets a consumption budget (number of calls, cost) for AI features, tracked at every sprint review." },
    "po:R4-C06": { text: "To rephrase tickets, the team uses a small model run in-house, which is enough for this task." },
    "po:R4-C07": { text: "The PO groups their requests to the AI into a single well-prepared prompt rather than rerunning the analysis for each new idea." },
    "po:R4-C08": { text: "The energy cost of an AI feature is one of the prioritisation criteria, alongside value and effort." },
    "po:R4-C09": { text: "The team caches the AI's answers to frequent questions, instead of rerunning the model each time." },
    "po:R4-C10": { text: "The PO asks AI suppliers for information on their models' consumption and takes it into account in their choice." },
    "po:R4-C11": { text: "The team tracks the number of calls to the AI model and tries every quarter to cut those that add nothing." },
    "po:R4-C12": { text: "The AI feature only runs when the user asks for it, rather than every time a screen is displayed." },
    "po:R4-C13": { text: "Before adding an AI feature to the backlog, the PO checks whether a simple rule or conventional automation would be enough." },
    "po:R4-C14": { text: "To test an idea, the team first builds a prototype without AI (mock-up, scenario acted out by hand) before building anything." },
    "po:R4-C15": { text: "The PO limits how often customer feedback is analysed automatically: weekly rather than with every new message." },
    "po:R4-U01": { text: "The PO insists on the most powerful model on the market for all the product's AI features, including rewording button labels. They believe the best quality is necessarily the best choice.", why: "The model is oversized for the task and no more frugal alternative was studied: environmental impact is ignored." },
    "po:R4-U02": { text: "The team has AI generate hundreds of text variants for an A/B test, when four would be enough.", why: "The volume of generations exceeds the need: energy is consumed for no benefit." },
    "po:R4-U03": { text: "Every time a ticket is edited, the AI assistant aligns its description with those of neighbouring tickets.", why: "A request is fired on every edit, however small: needless computation that increases consumption for no benefit." },
    "po:R4-U04": { text: "To analyse ten interviews, the PO submits the full transcripts to the most powerful model, several times over, to cross-check the results.", why: "Rerunning the same analysis several times on a large model multiplies consumption without the need justifying it." },
    "po:R4-U05": { text: "The AI feature is rolled out to everyone after a two-month pilot. Its energy cost is measured after the roll-out.", why: "The estimate comes after the decision: environmental impact is not taken into account before rolling out the feature." },
    "po:R4-U06": { text: "The team caches the AI's answers to frequent questions. The cache is rebuilt from scratch every night.", why: "Regenerating the whole cache every night reruns thousands of needless requests: only answers that have become outdated should be." },
    "po:R5-C01": { text: "The interface clearly shows when content has been generated by AI." },
    "po:R5-C02": { text: "A message reminds the user that AI can be wrong and that they should check important information." },
    "po:R5-C03": { text: "The PO tracks user feedback on the quality of the AI's answers and treats it as defects to fix in the backlog." },
    "po:R5-C04": { text: "When an AI-related incident occurs, the team raises the alert, fixes it and learns the lessons, without looking for someone to blame." },
    "po:R5-C05": { text: "The release notes state which features rely on AI and what their known limits are." },
    "po:R5-C06": { text: "The PO documents cases where the source data is incomplete or unreliable, so that decisions based on it are made with full knowledge." },
    "po:R5-C07": { text: "When a user challenges an AI answer, a clear channel lets them report it and reach a human." },
    "po:R5-C08": { text: "The feedback form sits right next to the AI's answer: thumbs up or down, and a free comment." },
    "po:R5-C09": { text: "The PO tells workshop participants that an AI transcribes the discussions and sends them the transcript to review." },
    "po:R5-C10": { text: "The PO explains to the sponsors what the AI feature can do, what it cannot do and the error rates observed." },
    "po:R5-C11": { text: "When the AI cannot answer a question, it offers the user the option of contacting an adviser." },
    "po:R5-C12": { text: "The stories for an AI feature include the information text for the user, reviewed by the legal team." },
    "po:R5-C13": { text: "AI-related incidents are presented at the sprint review with their cause and the actions decided, without looking for someone to blame." },
    "po:R5-C14": { text: "Roadmap communication clearly distinguishes what is delivered, what is experimental and what relies on AI." },
    "po:R5-C15": { text: "The PO asks the AI supplier for documentation on the training data and the known limits of its model." },
    "po:R5-U01": { text: "AI-generated summaries of customer reviews appear on the product page with no notice. Users think they are reading reviews written by people. Feedback is excellent, so the PO changes nothing.", why: "Users do not know the content comes from AI: good feedback does not make up for the lack of transparency." },
    "po:R5-U02": { text: "An assistant answers users with a first name and a photo. Nothing indicates that it is an AI.", why: "Users think they are talking to a person: not saying you are an AI is a lack of transparency." },
    "po:R5-U03": { text: "The use of AI by the summary block is described in the product's terms of use, which the user accepts when signing up.", why: "The notice is hidden in the terms of use: when reading the summary, the user does not know it comes from an AI." },
    "po:R5-U04": { text: "The PO presents the sponsors with a 94% correct-answer rate for the AI feature, measured by the team.", why: "The figure is presented without a protocol or limits: the sponsors cannot judge how reliable it is." },
    "po:R5-U05": { text: "Users can report a wrong AI answer from a link at the bottom of the page. The PO reviews the reports at the quarterly product review.", why: "Reported errors are only dealt with in the very long term: the channel exists but allows neither quick fixes nor quick information." },
    "po:R5-U06": { text: "The release notes list the features that rely on AI. Their known limits are documented in the team's wiki.", why: "The known limits are not communicated to users: mentioning AI is not enough, users must also be told its limits." },
    "po:R6-C01": { text: "The PO checks that the datasets used to test an AI feature represent all user profiles, not just the most common ones." },
    "po:R6-C02": { text: "Personas produced with the help of AI are reviewed to avoid stereotypes." },
    "po:R6-C03": { text: "An AI feature is tested with users of varied profiles: age, language, disability, digital confidence." },
    "po:R6-C04": { text: "The PO provides a non-AI alternative for users who do not want to or cannot use the assistant." },
    "po:R6-C05": { text: "The whole product team, including design and testing, is trained in the responsible use of AI, not just the developers." },
    "po:R6-C06": { text: "The PO recruits interview participants from varied profiles, including users who are not comfortable with digital tools." },
    "po:R6-C07": { text: "The team checks that the AI assistant understands misspelled questions, regional accents and messages in plain language." },
    "po:R6-C08": { text: "The PO adds accessibility stories to the backlog for AI features: screen reader, contrast, keyboard navigation." },
    "po:R6-C09": { text: "The roadmap sets aside time to fix the quality gaps observed between different user profiles." },
    "po:R6-C10": { text: "AI quality indicators are tracked by user segment, not just on average." },
    "po:R6-C11": { text: "The feedback analysed by AI includes feedback from the phone line and letters, not just from the app." },
    "po:R6-C12": { text: "A user who does not want to talk to the AI assistant can reach an adviser directly, without a complicated path." },
    "po:R6-C13": { text: "The PO asks the AI supplier how it tested its model for bias before selecting it." },
    "po:R6-C14": { text: "The team's personas include users with disabilities and carers." },
    "po:R6-C15": { text: "When an AI sorts or scores requests, the team reviews the criteria to make sure they do not penalise a group of users." },
    "po:R6-U01": { text: "The AI's prioritisation criteria are calibrated on feedback from the most active customers. The PO considers them the most representative and does not look at other profiles.", why: "The needs of less active or less visible users are ignored: the criteria are neither checked nor fair." },
    "po:R6-U02": { text: "The team decides not to provide an alternative to the AI assistant: users will have to get used to it.", why: "Users who cannot or do not want to use it lose access to the service: inclusion is ignored." },
    "po:R6-U03": { text: "The responsible AI training is open to the product team's developers and PO, by signing up with the PO.", why: "The team's designers and testers are not invited: the training is not offered to all members." },
    "po:R6-U04": { text: "The product team's responsible AI training is run in English by the supplier; several team members have little command of the language.", why: "The language excludes part of the team: the training is not offered to everyone on fair terms." },
    "po:R6-U05": { text: "Every month, the PO runs a workshop on AI good practices, with topics suggested by the team's developers.", why: "The needs of the team's other roles (design, testing, business) are not taken into account: the training does not address everyone in the same way." },
    "po:R6-U06": { text: "The AI supplier offers responsible AI training licences. The PO allocates them to the team members who ask for them.", why: "The training goes to those who ask for it, often the most confident: it is not actively offered to everyone." },
    "po:R7-C01": { text: "The PO identified a real user need, with a baseline measure, before proposing an AI feature. The team then measures the benefit achieved." },
    "po:R7-C02": { text: "AI prepares the context before a user interview (history, questions already asked). The PO can thus spend more time listening." },
    "po:R7-C03": { text: "An AI assistant helps new team members find past decisions and the product's history." },
    "po:R7-C04": { text: "An AI feature rephrases complex information in plain language for users." },
    "po:R7-C05": { text: "AI generates subtitles and transcripts of workshops to make them accessible to all participants." },
    "po:R7-C06": { text: "AI transcribes user interviews live. Freed from note-taking, the PO can focus on what the person is saying." },
    "po:R7-C07": { text: "AI rewrites confusing tickets in plain language, so that the whole team, technical or not, understands the need." },
    "po:R7-C08": { text: "An AI assistant answers developers' questions about the business context, so they can focus on design." },
    "po:R7-C09": { text: "AI prepares a first draft of the sprint review slides. The PO spends the time saved talking with stakeholders." },
    "po:R7-C10": { text: "AI flags feedback expressing real distress or urgency, so that the PO quickly has it handled by a person." },
    "po:R7-C11": { text: "An AI assistant prepares a summary of the indicators before the product review, so the discussion focuses on the decisions to be made." },
    "po:R7-C12": { text: "AI offers users contextual help in complex journeys, with direct access to an adviser if they get stuck." },
    "po:R7-C13": { text: "After a workshop, AI matches the needs expressed with those already identified so that the PO quickly spots the genuinely new topics." },
    "po:R7-C14": { text: "The PO tests an AI tool with the users concerned before deploying it: they only keep it if it improves their work." },
    "po:R7-C15": { text: "Every AI initiative on the roadmap is linked to a documented user need and a benefit indicator." },
    "po:R7-U01": { text: "The PO adds a generative AI assistant to the product because competitors are doing it and it will look good in the next announcement. No user need has been identified and no benefit is measured.", why: "AI is used for show, with no identified need or measured benefit for users." },
    "po:R7-U02": { text: "To stand out at a trade fair, the PO puts on the roadmap an AI feature whose purpose nobody knows yet.", why: "The feature is chosen for show, with no user need or expected benefit." },
    "po:R7-U03": { text: "AI automatically replies to negative reviews in the app store. The PO tracks the number of replies published every month.", why: "Nobody checks how users feel: the AI speaks on their behalf without creating value for them." },
    "po:R7-U04": { text: "The team adds to the roadmap an AI assistant requested by customer service; its success will be measured by the drop in call volume.", why: "The need and the measure of success come from the internal organisation: the benefit for users is neither identified nor measured." },
    "po:R7-U05": { text: "AI offers suggested replies on every screen of the product. The click-through rate on these suggestions appears in the team's dashboard.", why: "A click does not prove the user was helped: the real benefit is not measured." },
    "po:R7-U06": { text: "AI transcribes user interviews and extracts the needs from them. The PO works from the summaries and attends fewer interviews.", why: "The PO loses direct contact with users: AI replaces listening instead of freeing up time for it." },
  },
};
